/**
* Softly detect initial country and currency suggestion from browser locale / timezone without GPS.
*/
function detectInitialCountryAndCurrency() {
	const fallback = {
		countryCode: "US",
		currencyCode: "USD"
	};
	if (typeof navigator === "undefined") return fallback;
	try {
		const languages = navigator.languages || [navigator.language];
		for (const lang of languages) {
			if (!lang) continue;
			const parts = lang.split("-");
			if (parts.length >= 2) {
				const potentialCountry = parts[parts.length - 1].toUpperCase();
				if (potentialCountry.length === 2 && ISO_COUNTRIES_MAP.has(potentialCountry)) {
					const country = ISO_COUNTRIES_MAP.get(potentialCountry);
					return {
						countryCode: country.code,
						currencyCode: country.defaultCurrency || "USD"
					};
				}
			}
		}
		const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
		if (timeZone.startsWith("Asia/Kolkata") || timeZone.startsWith("Asia/Calcutta")) return {
			countryCode: "IN",
			currencyCode: "INR"
		};
		if (timeZone.startsWith("Europe/London")) return {
			countryCode: "GB",
			currencyCode: "GBP"
		};
		if (timeZone.startsWith("Asia/Tokyo")) return {
			countryCode: "JP",
			currencyCode: "JPY"
		};
		if (timeZone.startsWith("Australia/")) return {
			countryCode: "AU",
			currencyCode: "AUD"
		};
		if (timeZone.startsWith("America/Toronto") || timeZone.startsWith("America/Vancouver")) return {
			countryCode: "CA",
			currencyCode: "CAD"
		};
		if (timeZone.startsWith("Europe/Paris") || timeZone.startsWith("Europe/Berlin") || timeZone.startsWith("Europe/Madrid") || timeZone.startsWith("Europe/Rome")) return {
			countryCode: "FR",
			currencyCode: "EUR"
		};
	} catch {}
	return fallback;
}
